BEGIN
  coldefs := '';
  FOREACH c IN ARRAY cols LOOP
    IF c ~ '(_ids|_list|items|itens|tags|documents|attachments|prescriptions|medications|allergies|consents|checklist|kpis|etapas|charts|tables|predictions|recommendations|insights|opportunities|subtarefas|responsaveis|partial_payments|odontograma|json_schema|response_json_schema|metadata|integrations|channels|categories|contents|products|tasks|leads|sales|transactions|activities|emails|agendamentos|strengths|tactics|characteristics|criterios|history)$' THEN
      coltype := 'jsonb';
    ELSIF c ~ '^(is_|has_)' THEN
      coltype := 'boolean';
    ELSIF c ~ '(amount|price|cost|total|valor|score|points|rate|revenue|receita|quantity|stock|impressions|clicks|cliques|conversions|conversoes|investimento|investment|roi|cac|duration|duration_minutes|duration_seconds|progress|progresso|pontos|delay_days|days_offset|hours_before|installments|reorder_point|reorder_quantity|slot_duration|slot_duration_minutes|volume_busca)$' THEN
      coltype := 'numeric';
    ELSE
      coltype := 'text';
    END IF;
    coldefs := coldefs || format(', %I %s', c, coltype);
  END LOOP;

  FOREACH t IN ARRAY tbls LOOP
    EXECUTE format('CREATE TABLE IF NOT EXISTS public.%I (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_date timestamptz NOT NULL DEFAULT now(), updated_date timestamptz NOT NULL DEFAULT now(), created_by text %s)', t, coldefs);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (true) WITH CHECK (true)', t || '_authenticated_all', t);
  END LOOP;
END
